// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property() public {
        // Call sudoicideAnyone() and catch potential revert
        (bool success, ) = address(c).call(abi.encodeWithSignature("sudoicideAnyone()"));
        // General rule: the contract address should still have code after the call
        // If selfdestruct succeeded, code would be empty; if revert happened, code remains
        assertTrue(address(c).code.length > 0);
    }
}
